GOALS = {
    "goal": f"100 paying studios by June 2027 {EVIL}",
    "horizon": "2027-06",
    "objectives": [
        {"id": "O1", "title": "Prove studios pay", "quarter": "2026-Q4", "owner": "growth", "status": "active",
         "why": "Revenue before scale",
         "key_results": [
             {"id": "O1.1", "metric": "Paying studios", "baseline": 0, "target": 10, "current": 4,
              "history": [{"date": "2026-10-01", "value": 1}, {"date": "2026-11-01", "value": 4}]},
             {"id": "O1.2", "metric": "Monthly churn", "unit": "%", "baseline": 8, "target": 3, "current": 5},
             {"id": "O1.3", "metric": "Referrals", "target": 5}]},
        {"id": "O2", "title": "Ship invoicing", "status": "planned", "key_results": []}]}


def write(root: Path, data: dict) -> None:
    (root / "founder" / "goals.json").write_text(json.dumps(data), encoding="utf-8")


def link_slice(root: Path, objective: str) -> None:
    p = root / "founder" / "slices.json"
    data = json.loads(p.read_text(encoding="utf-8"))
    data["slices"][0]["objective"] = objective
    data["epics"]["INV"]["objective"] = objective
    p.write_text(json.dumps(data), encoding="utf-8")


def test_progress_runs_from_baseline_to_target_and_counts_down():
    assert goals.kr_progress({"baseline": 0, "target": 10, "current": 4}) == pytest.approx(0.4)
    assert goals.kr_progress({"baseline": 8, "target": 3, "current": 5}) == pytest.approx(0.6), "a cut counts down"
    assert goals.kr_progress({"target": 10, "current": 15}) == 1.0, "capped at 100%, baseline 0 when unset"
    assert goals.kr_progress({"baseline": 5, "target": 10, "current": 2}) == 0.0
    assert goals.kr_progress({"target": 5}) is None, "not measured yet"


def test_build_rolls_key_results_into_objectives_and_links_slices(root):
    write(root, GOALS)
    link_slice(root, "O1")
    g = goals.build(root)
    o1, o2 = g["objectives"]
    assert o1["progress"] == pytest.approx(0.5), "mean of the measured key results"
    assert [k["progress"] for k in o1["key_results"]] == [pytest.approx(0.4), pytest.approx(0.6), None]
    assert o1["key_results"][0]["owner"] == "growth", "a key result's owner defaults to its objective's"
    assert o1["slices"] == {"total": 1, "done": 1, "ids": ["S1"]} and o1["epics"] == ["INV"]
    assert o2["progress"] is None and o2["status"] == "planned"
    assert g["problems"] == []


@pytest.mark.parametrize("bad, words", [
    ({"objectives": [{"id": "1", "title": "x", "key_results": []}]}, "id must look like O1"),
    ({"objectives": [{"id": "O1", "title": "x"}, {"id": "O1", "title": "y"}]}, "used twice"),
    ({"objectives": [{"id": "O1", "title": "x", "status": "done"}]}, "status must be"),
    ({"objectives": [{"id": "O1", "title": "x", "owner": "ceo"}]}, "not a role"),
    ({"objectives": [{"id": "O1", "title": "x", "key_results": [{"id": "O2.1", "metric": "m", "target": 1}]}]}, "must look like O1.1"),
    ({"objectives": [{"id": "O1", "title": "x", "key_results": [{"id": "O1.1", "metric": "m", "target": "lots"}]}]}, "must be a number"),
    ({"objectives": [{"id": "O1", "title": "x", "key_results": [{"id": "O1.1", "metric": "m"}]}]}, "has no target"),
])
def test_check_names_each_problem(root, bad, words):
    write(root, bad)
    assert any(words in p for p in goals.problems(root)), goals.problems(root)
    assert goals.main(["check", "--root", str(root)]) == 1


def test_a_slice_naming_an_unknown_objective_fails_the_check(root):
    write(root, GOALS)
    link_slice(root, "O9")
    found = goals.problems(root)
    assert any("slice S1 names objective O9" in p for p in found) and any("epic INV" in p for p in found)
    (root / "founder" / "goals.json").unlink()
    assert goals.main(["check", "--root", str(root)]) == 1, "unknown objectives fail even with no goals.json"
    (root / "founder" / "goals.json").write_text("{not json", encoding="utf-8")
    assert goals.problems(root) == ["founder/goals.json is not valid JSON"]


def test_update_records_the_value_and_its_history(root):
    write(root, GOALS)
    assert goals.main(["update", "O1.1", "--value", "6", "--date", "2026-11-23", "--root", str(root)]) == 0
    assert goals.main(["update", "O1.1", "--value", "7", "--date", "2026-11-23", "--root", str(root)]) == 0
    kr = json.loads((root / "founder" / "goals.json").read_text(encoding="utf-8"))["objectives"][0]["key_results"][0]
    assert kr["current"] == 7 and kr["updated"] == "2026-11-23"
    assert [h["value"] for h in kr["history"]] == [1, 4, 7], "one value per day, oldest first"
    with pytest.raises(SystemExit):
        goals.main(["update", "O7.1", "--value", "1", "--root", str(root)])


def test_tickets_carry_their_objective_and_sub_tickets_inherit_it(root, fake):
    write(root, GOALS)
    run = lambda *a: tickets.main([*a, "--root", str(root)])  # noqa: E731
    with pytest.raises(SystemExit, match="--objective O1"):
        run("new", "product", "--title", "Pricing page", "--goal", "x", "--by", "growth")
    with pytest.raises(SystemExit, match="unknown objective"):
        run("new", "product", "--title", "Pricing page", "--goal", "x", "--objective", "O9")
    assert run("new", "product", "--title", "Pricing page", "--goal", "x", "--objective", "O1", "--by", "growth") == 0
    parent = max(n for n in fake.issues if "ticket" in fake.names(n))
    assert "goal:O1" in fake.names(parent) and "**Objective:** O1" in fake.issues[parent]["body"]
    assert run("new", "engineer", "--title", "Build it", "--goal", "y", "--parent", str(parent), "--by", "product") == 0
    child = max(n for n in fake.issues if "ticket" in fake.names(n))
    assert "goal:O1" in fake.names(child), "a sub-ticket inherits its parent's objective"


