def test_the_dashboard_and_summary_show_goals_as_text(root, fake):
    write(root, GOALS)
    fake.make("Pricing page", "", ["ticket", "role:growth", "goal:O1"])
    page = bd.page(bd.build(root, now=NOW))
    assert page.count("</script>") == 2 and "<img src=x" not in page, "the goal stays text"
    d = data_of(page)
    assert d["repo"]["goals"]["objectives"][0]["id"] == "O1"
    assert [t["goal"] for t in d["github"]["tickets"]] == ["O1"]
    summ = bd.summary(d)["goals"]
    assert [o["id"] for o in summ["objectives"]] == ["O1"], "only active objectives reach the portfolio"
    assert "history" not in json.dumps(summ) and "Revenue before scale" not in json.dumps(summ)
    html = bd.PAGE.read_text(encoding="utf-8")
    assert '["goals", "Goals", goalsTab]' in html and "function goalStrip" in html and "createElementNS" in html
    assert "goalLine(S.goals)" in (bd.PAGE.parent / "portfolio.html").read_text(encoding="utf-8")


